1	#!/usr/bin/env bun
2	/**
3	 * inject_stalled_continuation.ts — tell a run, in its own session, that it stopped
4	 * on a sentence having changed nothing, and may take one more turn.
5	 *
6	 * Usage: inject_stalled_continuation.ts --session PATH
7	 *
8	 * `domain/work/stalled-continuation.ts` decides when this is asked and writes the
9	 * note; this is the machinery that puts it where the next turn will read it. A user
10	 * turn in the saved session, the same shape `inject_ending_rejection.ts` uses and for
11	 * the same reason: atoma continues from the session when no prompt is given, so the
12	 * run sees the message it wrote and the note after it, then carries on by the
13	 * documented path.
14	 *
15	 * A session that was never written is a normal outcome for a run that failed before
16	 * its first turn. There is nobody to ask and nothing to append, so this says so and
17	 * leaves the caller to its ending.
18	 */
19	import { existsSync, readFileSync, writeFileSync } from "node:fs";
20	import { parseArgs } from "node:util";
21	import { stalledContinuationMessage } from "../../domain/work/stalled-continuation.ts";
22	import type { Session } from "../../domain/work/session.ts";
23	import { defineScript } from "./lib/script-ref.ts";
24	
25	export interface InjectStalledContinuationArgs {
26	  session: string;
27	}
28	
29	export const ref = defineScript<InjectStalledContinuationArgs>(import.meta.url);
30	
31	function main(): void {
32	  const { values } = parseArgs({
33	    args: Bun.argv.slice(2),
34	    options: { session: { type: "string" } },
35	  });
36	  const path = values.session;
37	  if (!path) {
38	    console.error("usage: inject_stalled_continuation.ts --session PATH");
39	    process.exit(2);
40	  }
41	  if (!existsSync(path)) {
42	    console.error(`inject_stalled_continuation: ${path} does not exist; nothing to do`);
43	    return;
44	  }
45	
46	  const session = JSON.parse(readFileSync(path, "utf8")) as Session;
47	  const messages = session.messages ?? [];
48	  messages.push({ role: "user", content: stalledContinuationMessage() });
49	  session.messages = messages;
50	  writeFileSync(path, JSON.stringify(session, null, 2));
51	  console.error(`inject_stalled_continuation: appended the continuation to ${path}`);
52	}
