1	#!/usr/bin/env bun
2	/**
3	 * should_continue_stalled.ts — should this run be asked, once, for one more turn?
4	 *
5	 * A run that ends on a text-only turn, changed nothing and called nobody may have
6	 * stopped on the sentence that announced its next step. #467 caught the shape when
7	 * the sentence ended on a colon; two more runs ended it with a full stop and were
8	 * recorded as `completed` / `changed=no`. The predicate is
9	 * `domain/work/stalled-continuation.ts`, which explains why each fact is read and
10	 * what the one extra turn costs.
11	 *
12	 * Usage: should_continue_stalled.ts --session FILE --output-file FILE
13	 *          --def-dir DIR --people-file FILE --changed true|false
14	 *
15	 * Writes `true` or `false` to stdout. The caller asks the question before starting a
16	 * second turn, so the answer reaches it as a value rather than through an exit code
17	 * that would fail the step.
18	 *
19	 * The facts come from the same places the other readers use: the ending and the last
20	 * assistant message out of the saved session (`read_run_ending.ts`'s parsers and
21	 * `domain/record/closing-report.ts`), the calls out of the closing message with the
22	 * same definitions and people list `check_ending.ts` counts against, and `--changed`
23	 * from the caller because the ops log is bash's to read. Asking a second, differently
24	 * spelled way here would be a second answer waiting to disagree with the one that
25	 * stopped the chain.
26	 */
27	import { existsSync, readFileSync } from "node:fs";
28	import { parseArgs } from "node:util";
29	import { lastTurnCalledTools } from "../../domain/record/closing-report.ts";
30	import { endingCalls } from "../../domain/work/ending-calls.ts";
31	import { shouldAskToContinue } from "../../domain/work/stalled-continuation.ts";
32	import { hasAgentDefinition } from "./extract_directive.ts";
33	import { readCalleesFile } from "./lib/callees.ts";
34	import { defineScript } from "./lib/script-ref.ts";
35	import { endingFromSession, parseSession } from "./read_run_ending.ts";
36	
37	export interface ShouldContinueStalledArgs {
38	  session: string;
39	  "output-file": string;
40	  "def-dir": string;
41	  "people-file"?: string;
42	  changed: string;
43	}
44	
45	export const ref = defineScript<ShouldContinueStalledArgs>(import.meta.url);
46	
47	function main(): void {
48	  const { values } = parseArgs({
49	    args: Bun.argv.slice(2),
50	    options: {
51	      session: { type: "string" },
52	      "output-file": { type: "string" },
53	      "def-dir": { type: "string" },
54	      "people-file": { type: "string" },
55	      changed: { type: "string" },
56	    },
57	  });
58	  const sessionPath = values.session;
59	  const outputFile = values["output-file"];
60	  const defDir = values["def-dir"];
61	  if (!sessionPath || !outputFile || !defDir) {
62	    console.error(
63	      "usage: should_continue_stalled.ts --session FILE --output-file FILE --def-dir DIR --people-file FILE --changed true|false",
64	    );
65	    process.exit(2);
66	  }
67	
68	  const session = parseSession(existsSync(sessionPath) ? readFileSync(sessionPath, "utf8") : undefined);
69	  const output = existsSync(outputFile) ? readFileSync(outputFile, "utf8") : "";
70	  const callees = readCalleesFile(values["people-file"]);
71	  const calls = endingCalls(output, {
72	    knowsAgent: (name) => hasAgentDefinition(name, defDir),
73	    humans: callees.humans,
74	  });
75	
76	  const answer = shouldAskToContinue({
77	    endedBecause: endingFromSession(session),
78	    lastTurnCalledTools: lastTurnCalledTools(session),
79	    changed: values.changed === "true",
80	    calledSomeone: calls.agents.length + calls.humans.length > 0,
81	  });
82	  console.log(answer ? "true" : "false");
83	  console.error(`should_continue_stalled: ${answer}`);
84	}
