1	#!/usr/bin/env bun
2	/**
3	 * dispatch_pr_validation.ts — hand a pull request to validation, from a workflow step.
4	 *
5	 * ## Why a person's command goes through validation rather than straight to the agent
6	 *
7	 * A person commenting `/<agent>` on a pull request is asking for a run, and the run
8	 * they are asking for is a judgement about a commit. Starting it immediately means
9	 * it reads a CI result that does not exist yet -- so it either waits with nothing
10	 * able to wake it, or reviews a commit whose checks have not run. Validation is the
11	 * thing that runs CI and waits, and it already dispatches whoever the result calls
12	 * for.
13	 *
14	 * So every agent start on a pull request goes through it, whoever asked: an agent's
15	 * handoff, a person's comment, and the re-validation after a push. One path, one
16	 * place that knows how to wait.
17	 *
18	 * ## Why the branch is resolved here when it is not passed in
19	 *
20	 * The two agent-side callers push a branch and pass the name they pushed. A person's
21	 * comment carries only a pull request number, so this script has to ask GitHub which
22	 * branch the pull request is from -- and a member can comment on a pull request from
23	 * a FORK, whose head branch is a branch of the fork rather than of this repository.
24	 * The read used to happen inline in the workflow step, which meant the name arrived
25	 * unchecked and `--ref` was handed one this repository does not have (#344). It is
26	 * resolved through the same three gates a `pr` run uses (`lib/pr-head-branch.ts`), and
27	 * a refusal is posted on the pull request in words the person can act on rather than
28	 * left as a red job nobody looks at.
29	 *
30	 * ## What `asked-by-person` changes
31	 *
32	 * One thing now: whether the "CI is running" comment is worth a person's thread
33	 * while validation waits. It no longer routes the verdict — a red check tells a
34	 * person either way, and a green one is gated on where the thread's ball sits,
35	 * not on who asked. See `notifyCiWaiting` and `ValidationInput.hold`.
36	 *
37	 * Usage:
38	 *   dispatch_pr_validation.ts --repo OWNER/REPO --number N [--branch B]
39	 *     [--asked-by-person] [--ask ID] [--commenter LOGIN]
40	 */
41	import { parseArgs } from "node:util";
42	import { dispatchPrValidation } from "../../adapters/actions/dispatch-targets.ts";
43	import { gh } from "../../adapters/github/gh.ts";
44	import { LLM_CONTEXT_TAG } from "../../adapters/github/tags.ts";
45	import { describePrHeadRefusal, validationNotDispatchedNotice } from "../../domain/work/pr-head-branch.ts";
46	import { isTrue } from "./lib/flags.ts";
47	import { resolvePrHeadBranch } from "./lib/pr-head-branch.ts";
48	import { defineScript } from "./lib/script-ref.ts";
49	
50	export interface DispatchPrValidationArgs {
51	  repo: string;
52	  number: string | number;
53	  /**
54	   * The branch to validate. Omitted, it is resolved from the pull request through
55	   * `lib/pr-head-branch.ts` — the path a person's comment takes, because the number is
56	   * all the comment carries.
57	   */
58	  branch?: string;
59	  "asked-by-person"?: string;
60	  /**
61	   * Who asked, for the refusal posted when no branch can be resolved. Only the
62	   * person-facing path has one: an agent's own dispatch has a branch by construction.
63	   */
64	  commenter?: string;
65	  /**
66	   * The ask comment id the run validation dispatches should claim (#285): the
67	   * person's command for the manual-comment path, the `waiting` ending for
68	   * `create_pr`'s, the pushing run's own claim for the re-validation after a push.
69	   * The answers-request check verifies the wait against THIS id, and the runner
70	   * writes its `atomaton:took` from it.
71	   */
72	  ask?: string;
73	}
74	
75	export const ref = defineScript<DispatchPrValidationArgs>(import.meta.url);
76	
77	function main(): void {
78	  const { values } = parseArgs({
79	    args: Bun.argv.slice(2),
80	    options: {
81	      repo: { type: "string" },
82	      number: { type: "string" },
83	      branch: { type: "string" },
84	      "asked-by-person": { type: "string" },
85	      commenter: { type: "string" },
86	      ask: { type: "string" },
87	    },
88	  });
89	
90	  const repo = values.repo ?? "";
91	  const number = values.number ?? "";
92	  if (!repo || !number) {
93	    console.error("usage: dispatch_pr_validation.ts --repo OWNER/REPO --number N [--branch B]");
94	    process.exit(2);
95	  }
96	
97	  const branch = (values.branch ?? "").trim() || resolvedBranch(repo, number, values.commenter ?? "");
98	
99	  // `dispatchPrValidation` reads the agent names from the pull request itself, so
100	  // there is nothing to pass but the target. `asked-by-person` travels as a
101	  // workflow input because it is a fact about THIS request rather than about the
102	  // pull request -- the same pull request can be validated by an agent's push and
103	  // by a person's comment, and the two route a failure differently.
104	  const dispatched = dispatchPrValidation(repo, Number(number), branch, {
105	    askedByPerson: isTrue(values["asked-by-person"]),
106	    ask: (values.ask ?? "").trim() || undefined,
107	  });
108	  if (!dispatched) {
109	    // Fatal, unlike most dispatches. The person asked for a run and nothing was
110	    // started; saying so in the log is the only place left, because nothing on this
111	    // workflow's path posts before validation -- the "CI is running" comment a
112	    // person may eventually see comes from validation itself, which never runs when
113	    // its own dispatch failed. (An earlier version of this comment blamed the
114	    // waiting comment this step used to post; that step is gone -- #271 moved the
115	    // comment into validation.)
116	    console.error(`::error::could not dispatch validation for PR #${number}; no agent will run`);
117	    process.exit(1);
118	  }
119	  console.error(`dispatched validation for PR #${number}`);
120	}
121	
122	/**
123	 * The pull request's head branch, or the end of this run.
124	 *
125	 * A refusal posts on the pull request and exits non-zero, because the person asked for
126	 * a run and none is coming: the notice is what they will read, and the red job is what
127	 * says the request never became a run. Tagged out of the model's context like every
128	 * other notice addressed to a person — a later run on this pull request would otherwise
129	 * read somebody else's refusal as something it was told.
130	 */
131	function resolvedBranch(repo: string, number: string, commenter: string): string {
132	  const { branch, refusal } = resolvePrHeadBranch(repo, Number(number));
133	  if (!refusal) return branch;
134	
135	  const notice = validationNotDispatchedNotice(commenter, Number(number), refusal);
136	  const posted = gh(
137	    "issue", "comment", number, "--repo", repo,
138	    "--body", [LLM_CONTEXT_TAG.write("exclude"), notice].join("\n"),
139	  );
140	  if (posted.code !== 0) {
141	    console.error(`Warning: could not post the refusal on #${number}: ${posted.stderr || posted.stdout}`);
142	  }
143	  console.error(
144	    `::error::${describePrHeadRefusal(Number(number), refusal)}; nothing was dispatched for PR #${number}`,
145	  );
146	  process.exit(1);
147	}
