1	#!/usr/bin/env bun
2	/**
3	 * resume_subtree.ts — bring back everything a stop held, not just the node it was
4	 * typed on.
5	 *
6	 * `/stop` reaches the work under the issue a person named, so `/resume` has to reach
7	 * the same work or the model is only half true: you would stop a chain with one
8	 * comment and restart it with one comment per node, which is the checklist this was
9	 * built to remove. See `domain/work/work-tree.ts`.
10	 *
11	 * ## What it does not need to remember
12	 *
13	 * Nothing. There is no record of what a particular stop covered, and there does not
14	 * have to be: a node is resumable when it is open, nothing is running on it, and its
15	 * last run ended on a stop. All three are readable from the tree and the thread, so
16	 * `/resume` asks the same question `/stop` asked rather than replaying an answer.
17	 *
18	 * ## The root is not started here
19	 *
20	 * The workflow already dispatches the node the comment was typed on, through
21	 * `resolve_resume_agent.ts` and the ordinary dispatch path. This starts the
22	 * descendants, so the two halves keep the one entry point each rather than one path
23	 * gaining a special case.
24	 *
25	 * Best-effort in every direction: a descendant that cannot be started is a warning.
26	 * The run the person asked for is already going, and failing this step would report
27	 * that none of it happened.
28	 *
29	 * Usage:
30	 *   resume_subtree.ts --number N [--notify LOGIN]
31	 */
32	import { parseArgs } from "node:util";
33	import { descendants, nodesToResume, resumeCandidates, subtree } from "../../domain/work/work-tree.ts";
34	import { dispatchRunner } from "../../adapters/actions/dispatch.ts";
35	import { lastEnding, readWorkTree } from "../../adapters/github/work-tree.ts";
36	import { mostRecentAgentOn } from "./resolve_resume_agent.ts";
37	import { defineScript } from "./lib/script-ref.ts";
38	
39	export interface ResumeSubtreeArgs {
40	  number: string | number;
41	  notify: string;
42	}
43	
44	export const ref = defineScript<ResumeSubtreeArgs>(import.meta.url);
45	
46	function main(): void {
47	  const { values } = parseArgs({
48	    args: Bun.argv.slice(2),
49	    options: { number: { type: "string" }, notify: { type: "string" } },
50	  });
51	
52	  if (!values.number) {
53	    console.error("usage: resume_subtree.ts --number N [--notify LOGIN]");
54	    process.exit(2);
55	  }
56	
57	  const repo = process.env.GITHUB_REPOSITORY ?? "";
58	  const root = Number(values.number);
59	  const { nodes, problems } = readWorkTree(repo, root);
60	  for (const problem of problems) console.error(`::warning::${problem}`);
61	  if (nodes.length === 0) {
62	    console.error(`Could not read the work under #${root}; nothing beyond it was resumed.`);
63	    return;
64	  }
65	
66	  // The endings come one node at a time, and only for the ones that could still be
67	  // resumed on structure alone. Asking every node in a large tree how its last run
68	  // ended would be a request per node for an answer most of them cannot use.
69	  const candidates = resumeCandidates(descendants(subtree(nodes, root), root));
70	  const stoppedLast = new Set(
71	    candidates.filter((node) => lastEnding(repo, node.number) === "stopped").map((node) => node.number),
72	  );
73	  const resumable = nodesToResume(candidates, stoppedLast);
74	
75	  if (resumable.length === 0) {
76	    console.error(`Nothing under #${root} was waiting to be resumed.`);
77	    return;
78	  }
79	
80	  const started: number[] = [];
81	  for (const node of resumable) {
82	    const agent = mostRecentAgentOn(repo, node.number);
83	    if (!agent) {
84	      console.error(`::warning::#${node.number} was stopped but nothing says which agent ran there; skipping.`);
85	      continue;
86	    }
87	    const outcome = dispatchRunner({
88	      context: `a resume on #${root} reached #${node.number}, which a stop had held`,
89	      agent,
90	      type: node.kind === "pull-request" ? "pr" : "issue",
91	      number: node.number,
92	      notify: (values.notify ?? "").trim(),
93	      repo,
94	    });
95	    if (outcome === "dispatched") started.push(node.number);
96	    else console.error(`::warning::could not resume ${agent} on #${node.number} (${outcome}).`);
97	  }
98	
99	  console.error(
100	    started.length > 0
101	      ? `Resumed under #${root}: ${started.map((n) => `#${n}`).join(", ")}`
102	      : `Nothing under #${root} could be resumed.`,
103	  );
104	}
