18	function main(): void {
19	  const body = process.env.PR_BODY ?? "";
20	  const prNumber = process.env.PR_NUMBER ?? "";
21	  const githubOutput = process.env.GITHUB_OUTPUT;
22	
23	  // Kept as a string: it is written straight to $GITHUB_OUTPUT, and an absent
24	  // tag has to render as empty so the caller's `if: ... != ''` stays false.
25	  // Prose only: a pull request body quoting the tag in a fenced sample does not
26	  // carry the link (#304).
27	  const parentIssue = PARENT_ISSUE_TAG.readProse(body);
28	  const parent = parentIssue === undefined ? "" : String(parentIssue);
29	  if (parent) console.error(`PR #${prNumber} belongs to issue #${parent}`);
30	  else console.error(`PR #${prNumber} has no parent-issue metadata`);
31	
32	  // One output, where there used to be two.
33	  //
34	  // `sub_number` was `closedIssueNumber(body)` and `parent_number` was this tag —
35	  // and the two were the SAME NUMBER every time, because `injectParentIssue` wrote
36	  // both from the run's one issue number. The only consumer fed `sub_number` to
37	  // `parentIssueOf` to find the issue's own parent, so which of the two it was
38	  // handed made no difference.
39	  //
40	  // Both halves of the old pair are gone with it: the `Closes` line no longer
41	  // exists to be read (#171), and a second spelling of one number is the shape
42	  // this repository keeps removing. See `issue-links.ts`'s `partOfLine`.
43	  if (githubOutput) appendFileSync(githubOutput, `parent_number=${parent}\n`);
44	}
